css:
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap");

/* ==========================================================================
   SIGNATURE / STAMP PICTURE
   ========================================================================== */

.bd_wrap .bd_sign {
  width: 260px;
  height: 175px;
  overflow: hidden;
  margin-left: auto;
}

.bd_wrap .bd_sign img,
body:last-child .print-format .bd_wrap .bd_sign img {
  width: 443px !important;
  max-width: none !important;
  max-height: none !important;
  margin: -85px 0 0 -95px;
}

/* Hide text because the signature image already contains the name */
.bd_wrap .bd_sign_text {
  display: none;
}

/* ==========================================================================
   GENERAL STYLING
   ========================================================================== */

.bd_wrap,
.bd_wrap * {
  -webkit-box-sizing: border-box;
  box-sizing: border-box;
}

.bd_wrap {
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  line-height: 1.5;
  color: #1f2733;
}

.bd_wrap table {
  width: 100%;
  border-collapse: collapse;
  border-spacing: 0;
}

.bd_wrap td,
.bd_wrap th {
  padding: 0;
  border: 0;
  vertical-align: top;
}

.bd_wrap img {
  border: 0;
  max-width: 100%;
  height: auto;
}

.bd_wrap div,
.bd_wrap p {
  margin: 0;
}

/* ==========================================================================
   HEADER
   ========================================================================== */

.bd_wrap .bd_card {
  border-radius: 14px;
  overflow: hidden;
  margin-bottom: 26px;
  border: 1px solid #e6e8ee;
}

.bd_wrap .bd_head td {
  padding: 26px 30px;
  vertical-align: middle;
}

.bd_wrap .bd_head_r {
  text-align: right;
}

.bd_wrap .bd_title {
  font-size: 38px;
  font-weight: 800;
  letter-spacing: 3px;
  line-height: 1.1;
  color: #fff;
  text-transform: uppercase;
}

.bd_wrap .bd_sub {
  margin-top: 8px;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.5px;
  color: #fff;
}

.bd_wrap .bd_pill {
  display: inline-block;
  margin-left: 8px;
  padding: 1px 9px;
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-radius: 20px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: #fff;
}

.bd_wrap .bd_logo {
  display: inline-block;
  padding: 10px 16px;
  border-radius: 10px;
  background: #fff;
}

.bd_wrap .bd_logo img,
body:last-child .print-format .bd_wrap .bd_logo img {
  display: block;
  width: auto !important;
  max-height: 54px;
  max-width: 190px;
}

.bd_wrap .bd_company {
  font-size: 20px;
  font-weight: 700;
  color: #fff;
}

/* ==========================================================================
   CUSTOMER AND QUOTATION DETAILS
   ========================================================================== */

.bd_wrap .bd_info {
  margin-bottom: 26px;
}

.bd_wrap .bd_info_l {
  width: 55%;
  padding-right: 20px;
}

.bd_wrap .bd_info_r {
  width: 45%;
}

.bd_wrap .bd_label {
  margin-bottom: 7px;
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 1.4px;
  text-transform: uppercase;
}

.bd_wrap .bd_name {
  font-size: 15px;
  font-weight: 700;
  color: #111827;
  margin-bottom: 2px;
}

.bd_wrap .bd_addr {
  margin-top: 3px;
  color: #2f3846;
}

/* Date and Valid Till: consistent spacing and alignment */
.bd_wrap .bd_kv {
  width: 100%;
  border-collapse: collapse;
}

.bd_wrap .bd_kv td {
  padding: 3px 0;
  line-height: 1.5;
  vertical-align: middle;
}

.bd_wrap .bd_kv tr:first-child td {
  padding-top: 0;
}

.bd_wrap .bd_kv td:first-child {
  color: #4b5563;
  padding-right: 14px;
  white-space: nowrap;
}

.bd_wrap .bd_kv td:last-child {
  text-align: right;
  font-weight: 600;
  color: #111827;
  white-space: nowrap;
}

/* ==========================================================================
   SERVICE DESCRIPTION
   ========================================================================== */

.bd_wrap .bd_desc {
  margin-bottom: 22px;
  padding: 14px 16px;
  border: 1px solid #e6e8ee;
  border-radius: 10px;
}

/* ==========================================================================
   ITEMS TABLE
   ========================================================================== */

.bd_wrap .bd_items {
  margin-bottom: 4px;
}

.bd_wrap .bd_items th {
  padding: 11px 14px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #fff;
  vertical-align: middle;
}

.bd_wrap .bd_items th:first-child {
  border-radius: 8px 0 0 8px;
}

.bd_wrap .bd_items th:last-child {
  border-radius: 0 8px 8px 0;
}

.bd_wrap .bd_items td {
  padding: 12px 14px;
  font-size: 13.5px;
  vertical-align: middle;
  border-bottom: 1px solid #eef0f4;
}

.bd_wrap .bd_row:nth-child(even) td {
  background: #f7f8fa;
}

.bd_wrap .bd_items tr {
  page-break-inside: avoid;
}

.bd_wrap .bd_section td {
  padding: 10px 14px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.4px;
  border-bottom: 0;
}

.bd_wrap .bd_l {
  text-align: left;
}

.bd_wrap .bd_r {
  text-align: right;
}

.bd_wrap .bd_c {
  text-align: center;
}

.bd_wrap .bd_bold {
  font-weight: 700;
  color: #111827;
}

.bd_wrap .bd_w_price {
  width: 23%;
}

.bd_wrap .bd_w_qty {
  width: 12%;
}

.bd_wrap .bd_w_total {
  width: 21%;
}

.bd_wrap .bd_item {
  font-size: 14px;
  font-weight: 700;
  color: #111827;
}

.bd_wrap .bd_item_desc {
  margin-top: 2px;
  font-size: 12px;
  color: #4b5563;
}

.bd_wrap .bd_uom {
  font-size: 11.5px;
  color: #4b5563;
}

/* ==========================================================================
   TOTALS
   ========================================================================== */

.bd_wrap .bd_sum {
  margin: 6px 0 4px;
}

.bd_wrap .bd_sum td {
  padding: 11px 14px;
  font-size: 13px;
  border-bottom: 1px solid #e3e6ec;
  color: #1f2733;
}

.bd_wrap .bd_sum td:last-child {
  text-align: right;
  font-weight: 600;
  color: #111827;
}

.bd_wrap .bd_sum .bd_grand td {
  padding-top: 14px;
  padding-bottom: 14px;
  font-size: 18px;
  font-weight: 800;
  border-bottom: 0;
}

.bd_wrap .bd_words {
  margin: 0 14px;
  font-size: 11.5px;
  font-style: italic;
  color: #2f3846;
}

/* ==========================================================================
   TERMS AND CONDITIONS / SIGNATURE
   ========================================================================== */

.bd_wrap .bd_bottom {
  margin-top: 30px;
  page-break-inside: avoid;
}

.bd_wrap .bd_bottom_l {
  width: 58%;
  padding-right: 24px;
}

.bd_wrap .bd_bottom_r {
  width: 42%;
  text-align: right;
}

/* Terms & Conditions heading uses the same heading style as other sections */
.bd_wrap .bd_bottom_l .bd_label {
  color: inherit;
  margin-bottom: 7px;
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 1.4px;
  text-transform: uppercase;
}

.bd_wrap .bd_terms {
  font-size: 11.5px;
  line-height: 1.6;
  color: #2f3846;
}

.bd_wrap .bd_thanks {
  margin-top: 16px;
  font-size: 15px;
  font-weight: 800;
}

.bd_wrap .bd_sign_name {
  font-size: 15px;
  font-weight: 700;
  color: #111827;
}

.bd_wrap .bd_sign_pos {
  font-size: 10.5px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #4b5563;
}

/* ==========================================================================
   COMPANY FOOTER
   ========================================================================== */

.pbd_footer {
  margin: 0 10px;
  padding: 11px 16px 12px;
  border-radius: 10px;
  background: #f3f4f7;
  color: #111827;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  line-height: 1.5em;
  text-align: center;
}

.pbd_footer_title {
  font-size: 15px;
  font-weight: 700;
}

html:
{% set pctx = doc._print_context or get_print_context(doc) %}
{%- set c = frappe.db.get_value("Company", doc.company, ["company_name", "company_logo", "custom_print_logo", "custom_brand_color", "custom_print_footer", "phone_no", "email"], as_dict=True) or {} -%}
{%- set brand = c.custom_brand_color or "#C8102E" -%}
{%- set logo = c.custom_print_logo or c.company_logo -%}
{%- set hx = "0123456789abcdef" -%}
{%- set b = brand|lower -%}
{%- if b|length == 7 and b.startswith("#") and (b[1:]|select("in", hx)|list|length == 6) -%}
  {%- set tint = "rgba(%d, %d, %d, 0.10)"|format(hx.index(b[1]) * 16 + hx.index(b[2]), hx.index(b[3]) * 16 + hx.index(b[4]), hx.index(b[5]) * 16 + hx.index(b[6])) -%}
{%- else -%}
  {%- set tint = "#eef0f4" -%}
{%- endif -%}
{%- set sig = frappe.db.get_value("Signature", doc.print_signature, ["signature_name", "position", "attach"], as_dict=True) if doc.print_signature else None -%}
{%- set sign_img = sig.attach if sig else None -%}
{%- set ncols = 4 + (0 if pctx.hide_qty else 1) + (1 if pctx.show_days else 0) -%}

<style>
  .bd_wrap .bd_head { background: {{ brand }}; }
  .bd_wrap .bd_accent { color: {{ brand }}; }
  .bd_wrap .bd_items th { background: {{ brand }}; }
  .bd_wrap .bd_section td { background: {{ tint }}; color: {{ brand }}; }
  .bd_wrap .bd_sum .bd_grand td { color: {{ brand }}; border-top: 2px solid {{ brand }}; }
  .bd_wrap .bd_thanks { color: {{ brand }}; }
  .bd_wrap .bd_subtotal td { font-weight: 700; }
</style>

<div class="bd_wrap">

  <div class="bd_card">
    <table class="bd_head">
      <tr>
        <td class="bd_head_l">
          <div class="bd_title">{{ _("Quotation") }}</div>
          <div class="bd_sub">
            {{ doc.name }}
            {% if doc.docstatus == 0 %}<span class="bd_pill">DRAFT</span>
            {% elif doc.docstatus == 2 %}<span class="bd_pill">CANCELLED</span>{% endif %}
          </div>
        </td>
        <td class="bd_head_r">
          {% if logo %}
            <span class="bd_logo"><img src="{{ logo }}" alt="{{ c.company_name or doc.company }}"></span>
          {% else %}
            <span class="bd_company">{{ c.company_name or doc.company }}</span>
          {% endif %}
        </td>
      </tr>
    </table>
  </div>

  <table class="bd_info">
    <tr>
      <td class="bd_info_l">
        <div class="bd_label bd_accent">{{ _("Quotation To") }}</div>
        <div class="bd_name">{{ doc.customer_name or doc.party_name }}</div>
        {% if doc.get("contact_display") and doc.contact_display != doc.customer_name %}<div>{{ doc.contact_display }}</div>{% endif %}
        {% if doc.get("contact_mobile") %}<div>{{ _("Phone") }}: {{ doc.contact_mobile }}</div>{% endif %}
        {% if doc.get("contact_email") %}<div>{{ _("Email") }}: {{ doc.contact_email }}</div>{% endif %}
        {% if doc.get("address_display") %}<div class="bd_addr">{{ doc.address_display }}</div>{% endif %}
      </td>
      <td class="bd_info_r">
        <table class="bd_kv">
          {% if doc.transaction_date %}<tr><td>{{ _("Date") }}</td><td>{{ doc.get_formatted("transaction_date") }}</td></tr>{% endif %}
          {% if doc.get("valid_till") %}<tr><td>{{ _("Valid Till") }}</td><td>{{ doc.get_formatted("valid_till") }}</td></tr>{% endif %}
          {% if doc.get("order_type") and doc.order_type != "Sales" %}<tr><td>{{ _("Type") }}</td><td>{{ doc.order_type }}</td></tr>{% endif %}
          {% if doc.get("event_date") %}<tr><td>{{ _("Event Date") }}</td><td>{{ doc.get_formatted("event_date") }}</td></tr>{% endif %}
          {% if doc.get("event_location") %}<tr><td>{{ _("Location") }}</td><td>{{ doc.event_location }}</td></tr>{% endif %}
        </table>
      </td>
    </tr>
  </table>

  {% if doc.get("desc") %}
  <div class="bd_desc">
    <div class="bd_label bd_accent">{{ _("Service Description") }}</div>
    {{ doc.desc }}
  </div>
  {% endif %}

  <table class="bd_items">
    <thead>
      <tr>
        <th class="bd_l">{{ _("Item Description") }}</th>
        {% if pctx.show_days %}<th class="bd_c">{{ _("Days") }}</th>{% endif %}
        <th class="bd_r bd_w_price">{{ _("Unit Price") }} ({{ doc.currency }})</th>
        {% if not pctx.hide_qty %}<th class="bd_c bd_w_qty">{{ _("Qty") }}</th>{% endif %}
        <th class="bd_r bd_w_total">{{ _("Total") }} ({{ doc.currency }})</th>
      </tr>
    </thead>
    <tbody>
      {% set ns = namespace(counter=0) %}
      {% for row in doc.items %}
        {% if row.get("is_section") or row.item_name == "Separator" or row.item_code == "Separator" %}
          <tr class="bd_section">
            <td colspan="{{ ncols - 1 }}">{{ row.get("section_title") or row.description or row.item_name }}</td>
          </tr>
        {% elif row.get("is_section_subtotal") %}
          <tr class="bd_subtotal">
            <td colspan="{{ ncols - 2 }}" class="bd_r">{{ _("Subtotal") }} ({{ row.get("section_title") or "" }}):</td>
            <td class="bd_r">{{ "{:,.2f}".format(row.amount or 0) }}</td>
          </tr>
        {% else %}
          {% set ns.counter = ns.counter + 1 %}
          <tr class="bd_row">
            <td class="bd_l">
              <div class="bd_item">{{ row.item_name or row.item_code }}</div>
              {% if row.description and row.description|striptags|trim != (row.item_name or "")|trim %}
                <div class="bd_item_desc">{{ row.description }}</div>
              {% endif %}
            </td>
            {% if pctx.show_days %}<td class="bd_c">{{ "{:,.0f}".format(row.get("number_of_days") or row.get("custom_number_of_days") or 1) }}</td>{% endif %}
            <td class="bd_r">{{ "{:,.2f}".format(row.rate or 0) }}</td>
            {% if not pctx.hide_qty %}
            <td class="bd_c">
              {{ row.get_formatted("qty", doc) }}
              {% if row.uom and row.uom != "Nos" %}<div class="bd_uom">{{ row.uom }}</div>{% endif %}
            </td>
            {% endif %}
            <td class="bd_r bd_bold">{{ "{:,.2f}".format(row.amount or 0) }}</td>
          </tr>
        {% endif %}
      {% endfor %}
    </tbody>
  </table>

  <table class="bd_sum">
    <tr><td>{{ _("Sub-Total") }}</td><td>{{ doc.get_formatted("total") }}</td></tr>
    {% if doc.discount_amount %}
    <tr>
      <td>{{ _("Discount") }}{% if doc.additional_discount_percentage %} ({{ doc.additional_discount_percentage }}%){% endif %}</td>
      <td>-{{ doc.get_formatted("discount_amount") }}</td>
    </tr>
    {% endif %}
    {% if not pctx.without_vat %}
      {% for tax in doc.taxes %}
        {% if tax.tax_amount %}
        <tr>
          <td>{{ tax.description }}{% if tax.rate %} ({{ tax.rate }}%){% endif %}</td>
          <td>{{ tax.get_formatted("tax_amount") }}</td>
        </tr>
        {% endif %}
      {% endfor %}
    {% endif %}
    <tr class="bd_grand">
      <td>{{ _("Grand Total") }}:</td>
      <td>{% if pctx.without_vat %}{{ doc.get_formatted("net_total") or doc.get_formatted("total") }}{% else %}{{ doc.get_formatted("grand_total") }}{% endif %}</td>
    </tr>
  </table>

  {% if doc.get("in_words") %}<div class="bd_words">{{ doc.in_words }}</div>{% endif %}

  {% if pctx.show_payment_terms and doc.payment_schedule %}
  <div class="bd_desc">
    <div class="bd_label bd_accent">{{ _("Payment Terms") }}</div>
    <table class="bd_items">
      <thead><tr><th class="bd_l">{{ _("Payment Term") }}</th><th class="bd_l">{{ _("Description") }}</th><th class="bd_r">{{ _("Amount") }} ({{ doc.currency }})</th></tr></thead>
      <tbody>
        {% for row in doc.payment_schedule %}
        <tr class="bd_row"><td class="bd_l">{{ row.payment_term or '' }}</td><td class="bd_l">{{ row.description or '' }}</td><td class="bd_r">{{ "{:,.2f}".format(row.payment_amount or 0) }}</td></tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
  {% endif %}

  <table class="bd_bottom">
    <tr>
      <td class="bd_bottom_l">
        {% if pctx.show_terms and doc.terms %}
          <div class="bd_label bd_accent">{{ _("Terms & Conditions") }}</div>
          <div class="bd_terms">{{ doc.terms }}</div>
        {% endif %}
        <div class="bd_thanks">{{ _("Thank You For Your Business") }}</div>
      </td>
      <td class="bd_bottom_r">
        {% if pctx.show_signature and sig %}
        <div class="bd_sign_wrap">
          {% if sign_img %}<div class="bd_sign"><img src="{{ sign_img }}" alt=""></div>{% endif %}
          <div class="bd_sign_text">
            <div class="bd_sign_name">{{ sig.signature_name }}</div>
            {% if sig.position %}<div class="bd_sign_pos">{{ sig.position }}</div>{% endif %}
          </div>
        </div>
        {% endif %}
      </td>
    </tr>
  </table>

</div>

<div id="footer-html" class="visible-pdf">
  <div class="pbd_footer" style="border-top: 3px solid {{ brand }};">
    <b class="pbd_footer_title" style="color: {{ brand }};">{{ c.company_name or doc.company }}</b>
    {% if c.custom_print_footer %}
      {% for line in c.custom_print_footer.split("\n") if line.strip() %}
        <br>{{ line.strip() }}
      {% endfor %}
    {% else %}
      {% if c.phone_no or c.email %}
        <br>
        {% if c.phone_no %}<b>Phone:</b> {{ c.phone_no }}{% endif %}
        {% if c.email %}<b>Email:</b> {{ c.email }}{% endif %}
      {% endif %}
    {% endif %}
  </div>
</div>
